class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.size() != t.size()) return false;
        map<char, int> cnt;
        for (int i = 0; i < (int)s.size(); i++) cnt[s[i]]++;
        for (int i = 0; i < (int)t.size(); i++) {
            if (--cnt[t[i]] < 0) return false;
        }
        return true;
    }
};
